import re
import time
import hashlib
from enum import Enum
from collections import deque
from typing import Optional, Dict, Any


class CircuitState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


class CircuitBreaker:
    def __init__(self, failure_threshold: int = 5, recovery_timeout: float = 30.0):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.state = CircuitState.CLOSED
        self.failure_count = 0
        self.last_failure_time: Optional[float] = None
        self.success_count = 0

    def record_success(self):
        self.failure_count = 0
        self.success_count += 1
        if self.state == CircuitState.HALF_OPEN:
            self.state = CircuitState.CLOSED

    def record_failure(self):
        self.failure_count += 1
        self.last_failure_time = time.time()
        if self.failure_count >= self.failure_threshold:
            self.state = CircuitState.OPEN

    def can_execute(self) -> bool:
        if self.state == CircuitState.CLOSED:
            return True
        if self.state == CircuitState.OPEN:
            if self.last_failure_time and \
               (time.time() - self.last_failure_time) > self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
                return True
            return False
        return True  # HALF_OPEN allows one attempt


class PDFStyleParser:
    """Parses CSS-like style declarations for PDF element styling."""

    # Pattern for matching nested CSS-like function calls in style values
    # Supports: rgb(), rgba(), linear-gradient(), calc(), var()
    _STYLE_VALUE_PATTERN = re.compile(
        r'^([a-zA-Z-]+)\s*:\s*'
        r'((?:[^;"]*(?:"[^"]*")*)*?)'
        r'\s*;?\s*$'
    )

    # Pattern for color validation - supports hex, rgb, named colors
    _COLOR_PATTERN = re.compile(
        r'^(?:#[0-9a-fA-F]{3,8}|'
        r'(?:rgb|hsl)a?\([^)]+\)|'
        r'[a-zA-Z]+)$'
    )

    # Pattern for validating calc() expressions in measurements
    _CALC_PATTERN = re.compile(
        r'^calc\(\s*((?:[0-9]+(?:\.[0-9]+)?(?:px|em|rem|%|pt|cm|mm|in)'
        r'(?:\s*[+\-*/]\s*)*)+)\s*\)$'
    )

    # Font family pattern - allows quoted and unquoted font names
    _FONT_FAMILY_PATTERN = re.compile(
        r'^(?:"[^"]+"|[a-zA-Z][a-zA-Z0-9 -]*)'
        r'(?:\s*,\s*(?:"[^"]+"|[a-zA-Z][a-zA-Z0-9 -]*))*$'
    )

    # Border shorthand pattern
    _BORDER_PATTERN = re.compile(
        r'^(?:(?:thin|medium|thick|[0-9]+(?:\.[0-9]+)?(?:px|em|pt))\s+)?'
        r'(?:none|hidden|dotted|dashed|solid|double|groove|ridge|inset|outset)'
        r'(?:\s+(?:#[0-9a-fA-F]{3,8}|(?:rgb|hsl)a?\([^)]+\)|[a-zA-Z]+))?$'
    )

    # Transform pattern for PDF element positioning
    _TRANSFORM_PATTERN = re.compile(
        r'^(?:(?:translate|scale|rotate|skew)(?:X|Y|Z|3d)?'
        r'\((?:[^()]*(?:\([^()]*\))*[^()]*)*\)\s*)+$'
    )

    def __init__(self):
        self._cache: Dict[str, Dict[str, str]] = {}
        self._cache_keys = deque(maxlen=1000)

    def _get_cache_key(self, style_text: str) -> str:
        return hashlib.md5(style_text.encode()).hexdigest()

    def parse_style_block(self, style_text: str) -> Dict[str, str]:
        """Parse a style block into property-value pairs."""
        cache_key = self._get_cache_key(style_text)
        if cache_key in self._cache:
            return self._cache[cache_key].copy()

        result = {}
        declarations = self._split_declarations(style_text)
        for decl in declarations:
            match = self._STYLE_VALUE_PATTERN.match(decl.strip())
            if match:
                prop = match.group(1).strip()
                value = match.group(2).strip()
                if self._validate_value(prop, value):
                    result[prop] = value

        self._cache[cache_key] = result
        self._cache_keys.append(cache_key)
        return result.copy()

    def _split_declarations(self, style_text: str) -> list:
        """Split style text into individual declarations."""
        declarations = []
        current = []
        paren_depth = 0
        in_quotes = False

        for char in style_text:
            if char == '"' and not in_quotes:
                in_quotes = True
            elif char == '"' and in_quotes:
                in_quotes = False
            elif char == '(' and not in_quotes:
                paren_depth += 1
            elif char == ')' and not in_quotes:
                paren_depth -= 1
            elif char == ';' and paren_depth == 0 and not in_quotes:
                declarations.append(''.join(current))
                current = []
                continue
            current.append(char)

        if current:
            declarations.append(''.join(current))
        return declarations

    def _validate_value(self, prop: str, value: str) -> bool:
        """Validate a style value based on its property type."""
        if prop in ('color', 'background-color', 'border-color'):
            return bool(self._COLOR_PATTERN.match(value))
        elif prop == 'font-family':
            return bool(self._FONT_FAMILY_PATTERN.match(value))
        elif prop == 'border':
            return bool(self._BORDER_PATTERN.match(value))
        elif prop == 'transform':
            return bool(self._TRANSFORM_PATTERN.match(value))
        return True  # Allow unknown properties


class PDFGenerator:
    """PDF generation with circuit breaker for external resource loading."""

    def __init__(self):
        self.circuit_breaker = CircuitBreaker(failure_threshold=3, recovery_timeout=10.0)
        self.style_parser = PDFStyleParser()
        self._pages: list = []

    def add_styled_element(self, element_type: str, content: str,
                           style: str, page: int = 0) -> bool:
        """Add a styled element to the PDF."""
        if not self.circuit_breaker.can_execute():
            return False

        try:
            parsed_style = self.style_parser.parse_style_block(style)
            element = {
                'type': element_type,
                'content': content,
                'style': parsed_style,
                'page': page
            }
            while len(self._pages) <= page:
                self._pages.append([])
            self._pages[page].append(element)
            self.circuit_breaker.record_success()
            return True
        except Exception:
            self.circuit_breaker.record_failure()
            return False

    def render_page(self, page_num: int) -> Optional[Dict[str, Any]]:
        """Render a page to a dictionary representation."""
        if page_num >= len(self._pages):
            return None
        return {
            'page': page_num,
            'elements': self._pages[page_num],
            'rendered_at': time.time()
        }
